// Local-only protocol fixture. Not loaded by the application.
const path=require('node:path'),fs=require('node:fs'),http=require('node:http'),os=require('node:os'),{spawnSync}=require('node:child_process');
const express=require('express'),{addonBuilder,getRouter}=require('stremio-addon-sdk');
const root=path.resolve(__dirname,'../..'),base='http://127.0.0.1:33333';
const film={id:'fixture:film',type:'movie',name:'Fixture Film',poster:base+'/poster.svg',releaseInfo:'2020',description:'Local protocol fixture',cast:['Fixture Actor','Second Actor'],director:['Fixture Director']};
const show={id:'fixture:show',type:'series',name:'Fixture Show',poster:base+'/poster.svg',releaseInfo:'2021',cast:['Show Actor'],videos:[{id:'fixture:show:1:1',title:'First episode',season:1,episode:1},{id:'fixture:show:2:1',title:'Second season',season:2,episode:1,streams:[{name:'Inline HTTP stream',url:base+'/video.webm'}]}]};
const builder=new addonBuilder({id:'org.nav.protocol-fixture',name:'Protocol fixture',version:'1.0.0',description:'Local integration test',types:['movie','series'],resources:['catalog','meta','stream','subtitles'],idPrefixes:['fixture:'],catalogs:[{id:'films',type:'movie',name:'Movies',extra:[{name:'search'},{name:'skip'}]},{id:'shows',type:'series',name:'Shows',extra:[{name:'search'}]}]});
const scratch=fs.mkdtempSync(path.join(os.tmpdir(),'nav-media-fixture-')),videoFile=path.join(scratch,'video.webm'),audioFile=path.join(scratch,'audio.wav');
for(const args of [['-f','lavfi','-i','color=c=black:s=320x180:r=10','-t','5','-c:v','libvpx','-an',videoFile],['-f','lavfi','-i','anullsrc=r=8000:cl=mono','-t','10',audioFile]])if(spawnSync('ffmpeg',['-hide_banner','-loglevel','error',...args],{stdio:'ignore'}).status!==0){fs.rmSync(scratch,{recursive:true,force:true});throw Error('Install ffmpeg to run the local media fixture')}
const seen=[];
builder.defineCatalogHandler(args=>{seen.push({resource:'catalog',...args});return Promise.resolve({metas:[args.type==='series'?show:film]})});
builder.defineMetaHandler(args=>{seen.push({resource:'meta',...args});return Promise.resolve({meta:args.type==='series'?show:film})});
builder.defineStreamHandler(args=>{seen.push({resource:'stream',...args});return Promise.resolve({streams:[{name:'Local HTTP stream',url:base+'/video.webm',subtitles:[{id:'en',lang:'English',url:base+'/captions.vtt'}]},{name:'Torrent fixture',infoHash:'0'.repeat(40)}]})});
builder.defineSubtitlesHandler(args=>{seen.push({resource:'subtitles',...args});return Promise.resolve({subtitles:[{id:'en',lang:'English',url:base+'/captions.vtt'}]})});
const tracks=[1,2,3].map((n)=>({wrapperType:'track',trackId:700+n,trackName:'Fixture cue '+n,artistName:'Fixture Composer',collectionId:500,collectionName:'Fixture Film (Original Soundtrack)',discNumber:1,trackNumber:n,trackTimeMillis:10000,artworkUrl100:base+'/poster.svg',previewUrl:'https://fixture.media.test/audio.wav',trackViewUrl:'https://fixture.media.test/track/'+n}));
const album={wrapperType:'collection',collectionId:500,collectionName:'Fixture Film (Original Soundtrack)',artistName:'Fixture Composer',trackCount:3,artworkUrl100:base+'/poster.svg',releaseDate:'2020-01-01T00:00:00Z'};
const fixture=express();fixture.get('/poster.svg',(req,res)=>res.type('svg').send('<svg xmlns="http://www.w3.org/2000/svg" width="300" height="450"><rect width="300" height="450" fill="#222"/><text x="150" y="225" fill="#ddd" font-family="sans-serif" font-size="24" text-anchor="middle">Fixture Film</text></svg>'));fixture.get('/video.webm',(req,res)=>res.sendFile(videoFile));fixture.get('/audio.wav',(req,res)=>res.sendFile(audioFile));fixture.get('/captions.vtt',(req,res)=>res.type('vtt').send('WEBVTT\n\n00:00.000 --> 00:04.000\nProvider subtitles\n'));
fixture.get('/__seen',(req,res)=>res.json(seen));
fixture.use('/fake-cinemeta',(req,res)=>{if(req.path.includes('/catalog/')){const params=req.path.split('/').at(-1),query=decodeURIComponent(params);res.json({metas:/fixture[ %]+film/i.test(query)?[film]:[]})}else res.json({meta:req.path.includes('/series/')?show:film})});
fixture.get('/fake-music/search',(req,res)=>res.json({results:req.query.entity==='album'?[album]:[]}));fixture.get('/fake-music/lookup',(req,res)=>res.json({results:String(req.query.id)==='500'?[album,...tracks]:tracks.filter(t=>String(t.trackId)===String(req.query.id))}));
fixture.use(getRouter(builder.getInterface()));
const registry=path.join(root,'.local/media-addons.json');if(fs.existsSync(registry))throw Error('Remove or back up installed test add-ons before running the isolated fixture');
const undici=require('undici'),original=undici.fetch,direct=new undici.Agent();undici.fetch=(url,options={})=>{const target=new URL(String(url));if(target.hostname==='v3-cinemeta.strem.io'){target.protocol='http:';target.host='127.0.0.1:33333';target.pathname='/fake-cinemeta'+target.pathname;return original(target,{...options,dispatcher:direct})}if(target.hostname==='itunes.apple.com'){target.protocol='http:';target.host='127.0.0.1:33333';target.pathname='/fake-music'+target.pathname;return original(target,{...options,dispatcher:direct})}if(target.hostname==='fixture.media.test'){target.protocol='http:';target.host='127.0.0.1:33333';return original(target,{...options,dispatcher:direct})}return original(url,options)};
require('../../catalog').searchCatalog=async()=>({items:[],provider:'Local fixture'});
const {handleMediaProviders}=require('../../media-providers');
const app=http.createServer(async(req,res)=>{const url=new URL(req.url,'http://127.0.0.1:3001');if(await handleMediaProviders(req,res,url))return;let filename;try{filename=path.join(root,decodeURIComponent(url.pathname==='/'?'/index.html':url.pathname))}catch{res.writeHead(400);res.end();return}if(!filename.startsWith(root+path.sep)||path.relative(root,filename).split(path.sep).some(part=>part.startsWith('.'))){res.writeHead(403);res.end();return}fs.readFile(filename,(error,data)=>{res.writeHead(error?404:200,{'Content-Type':filename.endsWith('.js')?'text/javascript':filename.endsWith('.css')?'text/css':'text/html'});res.end(error?'Not found':data)})});
const upstream=fixture.listen(33333,'127.0.0.1',()=>app.listen(3001,'127.0.0.1',()=>console.log('Local add-on/protocol fixture ready on 3001 and 33333')));
const cleanup=()=>{fs.rmSync(registry,{force:true});fs.rmSync(scratch,{recursive:true,force:true});app.close();upstream.close();setTimeout(()=>process.exit(0),100)};process.once('SIGTERM',cleanup);process.once('SIGINT',cleanup);
